[93746] = {"Une réponse ferme", {"Confrontez Belathaan Voeu-Radieux sur la route qui mène au sanctuaire d’Akir."}},
[93786] = {"Message ensanglanté", {"Terrassez 12 journaliers de Ruissepré et retournez voir Krom’rosh pour l’informer de votre succès."}},
[93787] = {"Un festin à portée de main", {"Volez 6 sacoches de nourriture à la ferme de l’Alliance à Ruissepré et retournez voir Krom’rosh."}},
[93788] = {"Lames réclamées", {"Récupérez 10 haches d’abattage sur les bûcherons du camp de bûcherons de Turner pour Kreza Sombreronce, à Rog’mar."}},
[93791] = {"Parler à Belann", {"Parlez à Belann Vif-Bois à Valanaar."}},
[93797] = {"La brise dans les branches", {"Apportez un rameau imprégné de vent à Belann Vif-Bois, à Valanaar."}},
[93835] = {"La confrontation avec Lorthuna", {"Prenez le portail vers les hauteurs des flèches Rohashi et rejoignez Elaadrin Trombecalme et Ayessa Chantelaube dans leur confrontation avec la grande prêtresse Lorthuna."}},
[93836] = {"Le destin de Zéphras", {"Parlez à Talaanis Chantelombre à Valanaar."}},
[93926] = {"Le guet occidental", {"Trouvez le garde-paix Vaaniel à la tour de guet occidentale."}},
[93927] = {"Une dernière demande", {"Récupérez la note trouvée à proximité de la dépouille du garde-paix et lisez-la pour décider d’un plan d’action."}},
[93948] = {"Livraison de chevalière", {"Apportez la chevalière de la famille Chantelombre à Talaanis Chantelombre, à Valaanar."}},
[93949] = {"Les insectes ont des oreilles", {"Tuez des sauteciels à Valanaar jusqu’à avoir éliminé 8 sauteciels enchantés."}},
[93951] = {"Sa plus belle plume", {"Collectez 8 plumes de duvet d’hippogriffe dans les hautes-terres de Shen’dar."}},
