[95507] = {"Le gibier de Vrang", {"Récupérez 8 gibiers piégés dans les pièges déclenchés un peu partout dans les Tarides."}},
[95508] = {"Des invités indésirables", {"Aidez Walton à survivre à la rencontre avec Terry Grangodet et les soldats de Kul Tiras."}},
[95511] = {"Première virée à dos de sabre", {"Examinez les sabres de monte pour choisir votre première monture."}},
[95534] = {"Le mystère de Strahnbrande", {"Résolvez le mystère de Strahnbrande et rapportez vos découvertes à Hautebrande."}},
[95561] = {"Pomme de reinette et pomme d’api", {"Trouvez 6 pommes fraîches pour Tessa Aube-Radieuse, au donjon de Fort-Lointain."}},
[95562] = {"Des têtes à couper", {"Tuez Chogg’Zac dans les grottes sous Clairsoleil et récupérez ses têtes pour l’apprentie Claire."}},
[95601] = {"Les qui sont violets", {"Tuez 5 brutes surpuissantes et 10 ritualistes du Crépuscule et retournez voir Frappe-orteils à Clairsoleil."}},
[95602] = {"La lumière qui fait malade", {"Détruisez 5 cercles rituels du Crépuscule dans les grottes situées sous Clairsoleil."}},
[95603] = {"Des chauves-souris dans le beffroi", {"Tuez 5 chauves-souris de la pénombre nichées dans la cathédrale de Fort-Lointain pour sœur Rolande."}},
[95613] = {"Lumière perpétuelle", {"Apportez 5 bougies sanctifiées à sœur Rolande, au donjon de Fort-Lointain."}},
[95615] = {"In Memoriam", {"Déposez 3 bougies mémorielles sur les tombes du cimetière de la chapelle pour sœur Rolande, au donjon de Fort-Lointain."}},
[95621] = {"Des problèmes dans la vallée", {"Rendez-vous jusqu’à l’épave de la caravane et apprenez-en davantage sur les raisons de la venue des Kultirassiens."}},
[95642] = {"Abominables magies", {"Absorbez 25 échantillons dans le catalyseur de cristal auprès des sectateurs du Marteau du crépuscule et des cercles rituels du Crépuscule dans la grotte sous Clairsoleil, pour l’apprentie Claire."}},
[95643] = {"Purge indifférenciée", {"Tuez 5 ritualistes du Crépuscule et 5 brutes surpuissantes dans les grottes sous Clairsoleil."}},
[95646] = {"Horreurs dans les hautes-terres", {"Tuez une horreur des hautes-terres dans les excavations et rapportez son cœur-racine à Rethiel le Gardien vert dans les Paluns."}},
[95647] = {"Perdu dans les fourrés", {"Trouver Ardin Grassman dans les excavations"}},
[95663] = {"Rumeurs sur les Gueules-de-Dragon", {"Rendez-vous dans les Paluns et retrouvez l’agente nécrotraqueuse dans les collines qui dominent le campement gueule-de-dragon."}},
[95664] = {"Le savoir des anciens", {"Apportez la relique des Titans à la cime des Anciens, aux Pitons-du-Tonnerre, et cherchez quelqu’un qui saura vous en apprendre davantage à son sujet."}},
[95682] = {"Gueule-de-bois", {"Éliminez les forces des Gueules-de-dragon présentes sur le site de fouilles, puis retournez auprès de l’agent des nécrotraqueurs à l’extérieur et remettez-lui tout ce que vous aurez récupéré."}},
[95697] = {"Goûts changeants", {"Pénétrez dans les excavations des Paluns et rapportez de la viande de raptor des fourrés."}},
[95737] = {"À la recherche de Caitlin", {"Parlez à Caitlin Grassman au port de Menethil."}},
[95748] = {"Les anciennes légendes des Gurubashi", {"Utilisez la peau et le charbon pour créer une reproduction de la tablette de la troisième légende trolle."}},
[95753] = {"Le défi du loup du désert", {"Atteignez l’autre totem, à l’extrémité de l’énorme squelette, avant la fin du temps imparti."}},
[95770] = {"À la recherche de la cité perdue", {"Explorez le récif Infâme et trouvez l’entrée de la grotte."}},
[95772] = {"À la recherche de Lame-chantante", {"Cherchez Daewyn, le frère de Dorin Lame-chantante, dans les Excavations de Whelgar."}},
