[97914] = {"Vers de nouveaux horizons", {"Remettez la lettre de Thundris à Baros Alexston, à Hurlevent.","","Thundris a mentionné un navire d’Auberdine qui peut vous y conduire."}},
[97915] = {"Introduction au camping : l’alchimie", {"Parlez à l’alchimiste Mallory, dans la forêt d’Elwynn près de Hurlevent, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main."}},
